/**
 * Whether a local day's recorded activity load can be totalled.
 */
export enum FfiDayLoadStatus {
  /**
   * Every activity that day carries a recorded load, an explicit zero included.
   */
  Complete,
  /**
   * Some activities carry a load and some do not; the total is the known part.
   */
  Partial,
  /**
   * The day has activities and none carries a load.
   */
  Unavailable,
  /**
   * The day has no activities.
   */
  Rest,
}

const FfiConverterTypeFfiDayLoadStatus = (() => {
  type TypeName = FfiDayLoadStatus;
  class FFIConverter extends AbstractFfiConverterByteArray<TypeName> {
    readFromCursor(c: Cursor): TypeName {
      switch (c.readI32()) {
        case 1:
          return FfiDayLoadStatus.Complete;
        case 2:
          return FfiDayLoadStatus.Partial;
        case 3:
          return FfiDayLoadStatus.Unavailable;
        case 4:
          return FfiDayLoadStatus.Rest;
        default:
          throw new UniffiInternalError.UnexpectedEnumCase();
      }
    }
    writeIntoCursor(value: TypeName, c: Cursor): void {
      switch (value) {
        case FfiDayLoadStatus.Complete:
          return c.writeI32(1);
        case FfiDayLoadStatus.Partial:
          return c.writeI32(2);
        case FfiDayLoadStatus.Unavailable:
          return c.writeI32(3);
        case FfiDayLoadStatus.Rest:
          return c.writeI32(4);
      }
    }
    allocationSize(value: TypeName): number {
      return 4;
    }
  }
  return new FFIConverter();
})();

