          size += FfiConverterFloat64.allocationSize(inner.r);
          size += FfiConverterUInt32.allocationSize(inner.n);
          size += FfiConverterFloat64.allocationSize(inner.low);
          size += FfiConverterFloat64.allocationSize(inner.high);
