/**
 * What one attempt at a ride's upload came to. The review screen branches on
 * it, and the drain stops on every outcome but a settled ride.
 *
 * The wire carries the variant's position, so the order is the contract:
 * append, never reorder. The discriminants start at one so no member is falsy.
 */
export enum FfiUploadOutcome {
  /**
   * intervals.icu took the ride.
   */
  Uploaded = 1,
  /**
   * The grant lacks write permission. Every other ride would meet it too.
   */
  PermissionBlocked = 2,
  /**
   * The credential was refused. The ride waits with its attempts intact.
   */
  AuthExpired = 3,
  /**
   * A rejection retrying the same bytes cannot fix. The ride parks.
   */
  Rejected = 4,
  /**
   * A failure worth another attempt once the backoff has run.
   */
  Retriable = 5,
  /**
   * The request never reached intervals.icu.
   */
  Network = 6,
  /**
   * The FIT, or a manual entry's body, is not on the device.
   */
  Missing = 7,
  /**
   * The ride belongs to an athlete other than the one signed in, or to
   * nobody, and is held for its own athlete.
   */
  OtherAthlete = 8,
  /**
   * The ride was not pending, or another run holds it: nothing was sent.
   */
  NotStarted = 9,
}

const FfiConverterTypeFfiUploadOutcome = (() => {
  type TypeName = FfiUploadOutcome;
  class FFIConverter extends AbstractFfiConverterByteArray<TypeName> {
    readFromCursor(c: Cursor): TypeName {
      switch (c.readI32()) {
        case 1:
          return FfiUploadOutcome.Uploaded;
        case 2:
          return FfiUploadOutcome.PermissionBlocked;
        case 3:
          return FfiUploadOutcome.AuthExpired;
        case 4:
          return FfiUploadOutcome.Rejected;
        case 5:
          return FfiUploadOutcome.Retriable;
        case 6:
          return FfiUploadOutcome.Network;
        case 7:
          return FfiUploadOutcome.Missing;
        case 8:
          return FfiUploadOutcome.OtherAthlete;
        case 9:
          return FfiUploadOutcome.NotStarted;
        default:
          throw new UniffiInternalError.UnexpectedEnumCase();
      }
    }
    writeIntoCursor(value: TypeName, c: Cursor): void {
      switch (value) {
        case FfiUploadOutcome.Uploaded:
          return c.writeI32(1);
        case FfiUploadOutcome.PermissionBlocked:
          return c.writeI32(2);
        case FfiUploadOutcome.AuthExpired:
          return c.writeI32(3);
        case FfiUploadOutcome.Rejected:
          return c.writeI32(4);
        case FfiUploadOutcome.Retriable:
          return c.writeI32(5);
        case FfiUploadOutcome.Network:
          return c.writeI32(6);
        case FfiUploadOutcome.Missing:
          return c.writeI32(7);
        case FfiUploadOutcome.OtherAthlete:
          return c.writeI32(8);
        case FfiUploadOutcome.NotStarted:
          return c.writeI32(9);
      }
    }
    allocationSize(value: TypeName): number {
      return 4;
    }
  }
  return new FFIConverter();
})();

